import{Et as e,Ot as t,n,qt as r}from"./chunks/framework.B_qehzBO.js";var i=JSON.parse(`{"title":"Redes — La caja de herramientas del internet abierto","description":"TCP/IP, DNS, proxies, túneles VLESS, redes de borde — redes prácticas y profundas para entornos hostiles.","frontmatter":{"title":"Redes — La caja de herramientas del internet abierto","description":"TCP/IP, DNS, proxies, túneles VLESS, redes de borde — redes prácticas y profundas para entornos hostiles."},"headers":[],"relativePath":"es/skills/networking/index.md","filePath":"es/skills/networking/index.md"}`),a={name:`es/skills/networking/index.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h1 id="redes-—-la-caja-de-herramientas-del-internet-abierto" tabindex="-1">Redes — La caja de herramientas del internet abierto <a class="header-anchor" href="#redes-—-la-caja-de-herramientas-del-internet-abierto" aria-label="Permalink to “Redes — La caja de herramientas del internet abierto”">​</a></h1><p>Las redes son mi especialidad bajo presión: construyo para redes que resisten activamente. Eso significa fluidez desde los paquetes hasta las plataformas — cómo muere un handshake TLS, por qué se rompe un enlace de suscripción, dónde filtra DNS un túnel.</p><h2 id="mapa-de-competencias" tabindex="-1">Mapa de competencias <a class="header-anchor" href="#mapa-de-competencias" aria-label="Permalink to “Mapa de competencias”">​</a></h2><table tabindex="0"><thead><tr><th>Capa</th><th>Habilidades</th></tr></thead><tbody><tr><td>Fundamentos</td><td>TCP/IP, DNS, HTTP/2–3, TLS, enrutamiento, NAT, análisis de capturas</td></tr><tr><td>Tecnología proxy</td><td>VLESS, VMess, Trojan, Reality; configs de Clash, v2ray, sing-box</td></tr><tr><td>Borde y CDN</td><td>Cloudflare Workers, KV, distribución en 300+ PoPs, reglas WAF</td></tr><tr><td>Diagnóstico</td><td>Escaneo de puertos, TCP ping, inspección TLS (<a href="/Usf/es/projects/netpilot/">NetPilot</a>)</td></tr><tr><td>Operaciones</td><td>Redundancia multiplataforma, migraciones sin downtime</td></tr></tbody></table><p>Este es el dominio donde viven mis <a href="/Usf/es/projects/netpilot/">herramientas de red</a>, y moldea todo lo demás: mis puentes de API asumen throttling, mis routers asumen la muerte de upstreams, y mis despliegues asumen que cualquier plataforma puede desaparecer de la noche a la mañana. La redundancia no es paranoia — es el SLA mínimo de una conexión libre y abierta.</p><blockquote><p>Una red de la que puedes fiarte se construye, no se espera.</p></blockquote>`,6)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};